package dev.gbppimentel.snapcompanion;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class SnapUiStateTest {
 private LiveStabilizer.Stable field(String key,String value,long at){return new LiveStabilizer.Stable(key,value,.95f,at,at,3,"screen","default","visible");}
 private Map<String,LiveStabilizer.Stable> course(long at){return Map.of("course",field("course","park-day",at),"researchLevel",field("researchLevel","2",at));}
 @Test public void courseFollowsVerifiedRunAndClearsAtCampWithoutManualFallback(){var state=new SnapUiState();var choice=state.update("default","12",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);assertEquals("park-day",choice.course());assertEquals(2,choice.level());for(long at=9000;at<45000;at+=8000)state.update("default","12",true,true,true,LiveReading.Scene.EXPEDITION,at,Map.of(),at);var run=state.update("default","12",true,true,true,LiveReading.Scene.EXPEDITION,45000,Map.of(),45000);assertEquals("research",run.phase());assertEquals("park-day",run.course());var camp=state.update("default","12",true,true,true,LiveReading.Scene.MENU,50000,course(1000),50000);assertEquals("",camp.course());assertEquals("camp",camp.phase());var unknown=state.update("default","12",true,true,true,LiveReading.Scene.EXPEDITION,51000,course(1000),51000);assertEquals("",unknown.course());}
 @Test public void backgroundAndOtherProfileReadingsNeverBecomeCurrentGameContext(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);assertEquals("background",state.update("default","1",true,false,false,LiveReading.Scene.EXPEDITION,1000,course(1000),2000).phase());var next=state.update("other","2",true,true,true,LiveReading.Scene.EXPEDITION,3000,course(3000),3000);assertEquals("",next.course());assertEquals(0,next.level());}
 @Test public void evaluationAndPauseDrivePanelsButStaleScreensDoNot(){var state=new SnapUiState();assertEquals("evaluation",state.update("default","1",true,true,true,LiveReading.Scene.EVALUATION,1000,Map.of(),1000).phase());assertEquals("paused",state.update("default","1",true,true,true,LiveReading.Scene.PAUSED,2000,Map.of(),2000).phase());assertEquals("playing",state.update("default","1",true,true,false,LiveReading.Scene.EVALUATION,2000,Map.of(),20000).phase());assertEquals("waiting",state.update("default","",false,false,false,LiveReading.Scene.EVALUATION,2000,Map.of(),21000).phase());}
 @Test public void aNewCourseSelectionCannotReuseAnEarlierDayVariant(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,2000,Map.of(),2000);state.update("default","1",true,true,true,LiveReading.Scene.RESULTS,4000,Map.of(),4000);var choosing=state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,5000,course(1000),5000);assertEquals("",choosing.course());var night=Map.of("course",field("course","park-night",6000),"researchLevel",field("researchLevel","1",6000));var confirmed=state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,6500,night,6500);assertEquals("park-night",confirmed.course());assertEquals(1,confirmed.level());}
 @Test public void newExpeditionAfterResultsAndCaptureGapsDropOldCourse(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);state.update("default","1",true,true,true,LiveReading.Scene.RESULTS,2000,Map.of(),2000);assertEquals("",state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,3000,course(1000),3000).course());var another=new SnapUiState();another.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);assertEquals("",another.update("default","1",true,true,false,LiveReading.Scene.UNKNOWN,1000,Map.of(),12000).course());}
 @Test public void newCourseDoesNotAdoptEarlierCourseLevel(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);var night=Map.of("course",field("course","park-night",3000),"researchLevel",field("researchLevel","2",2000));var current=state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,3000,night,3000);assertEquals("park-night",current.course());assertEquals(0,current.level());var confirmed=state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,4000,Map.of("course",field("course","park-night",4000),"researchLevel",field("researchLevel","1",4000)),4000);assertEquals(1,confirmed.level());}
 @Test public void replayingAnOldSelectionAfterBackgroundCannotLowerTheResetBoundary(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);state.update("default","1",true,false,false,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),2000);var stale=state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),2500);assertEquals("",stale.course());assertEquals(0,stale.level());}
 @Test public void continuouslyUnrecognizedFramesDoNotKeepAnOldCourseAlive(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,2000,Map.of(),2000);assertEquals("park-day",state.update("default","1",true,true,true,LiveReading.Scene.UNKNOWN,5000,course(1000),5000).course());assertEquals("",state.update("default","1",true,true,true,LiveReading.Scene.UNKNOWN,13000,course(1000),13000).course());assertEquals("",state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,13500,course(1000),13500).course());assertEquals("park-day",state.update("default","1",true,true,true,LiveReading.Scene.EXPEDITION,14000,course(14000),14000).course());}
 @Test public void introCannotReuseAnOlderLevelEvenWhenCourseEvidenceBeganOnTheMap(){var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.COURSE_SELECTION,1000,course(1000),1000);var c=new LiveStabilizer.Stable("course","park-day",.99f,1000,2000,3,"screen","default","course title");var intro=state.update("default","1",true,true,true,LiveReading.Scene.COURSE_INTRO,2000,Map.of("course",c,"researchLevel",field("researchLevel","2",1000)),2000);assertEquals("park-day",intro.course());assertEquals(0,intro.level());}
 @Test public void briefUnreadableSelectionKeepsOnlyTheDeskAndNeverAnOldSubject(){
  var state=new SnapUiState();var prior=Map.of("subject",field("subject","810",1000),"category",field("category","3",1000));
  state.update("default","1",true,true,true,LiveReading.Scene.PHOTO_SELECTION,1000,prior,1000);
  var brief=state.update("default","1",true,true,true,LiveReading.Scene.UNKNOWN,1500,prior,1500);assertEquals("selection",brief.phase());assertEquals(0,brief.subject());
  assertEquals("playing",state.update("default","1",true,true,true,LiveReading.Scene.UNKNOWN,2600,prior,2600).phase());
  assertEquals("playing",state.update("default","1",true,true,false,LiveReading.Scene.UNKNOWN,1500,prior,2700).phase());
 }
 @Test public void knownExitBackgroundAndNewProcessEndSelectionContinuityImmediately(){
  for(var scene:List.of(LiveReading.Scene.EVALUATION,LiveReading.Scene.MENU,LiveReading.Scene.EXPEDITION,LiveReading.Scene.PAUSED)){
   var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.PHOTO_SELECTION,1000,Map.of(),1000);assertNotEquals("selection",state.update("default","1",true,true,true,scene,1200,Map.of(),1200).phase());
  }
  var state=new SnapUiState();state.update("default","1",true,true,true,LiveReading.Scene.PHOTO_SELECTION,1000,Map.of(),1000);assertEquals("background",state.update("default","1",true,false,true,LiveReading.Scene.UNKNOWN,1200,Map.of(),1200).phase());
  state.update("default","1",true,true,true,LiveReading.Scene.PHOTO_SELECTION,2000,Map.of(),2000);assertNotEquals("selection",state.update("default","2",true,true,true,LiveReading.Scene.UNKNOWN,2200,Map.of(),2200).phase());
 }
}
